package cn.haiduo;
import cn.haiduo.inventory.InventoryService;
import cn.haiduo.orders.CsvOrders;
import cn.haiduo.audit.Audit;
import java.util.*;
import java.math.BigDecimal;
import java.security.Principal;
import jakarta.servlet.http.HttpSession;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
@RestController @RequestMapping("/api") public class OperationsController {
 private final JdbcTemplate db;private final SessionController sessions;private final InventoryService inventory;
 public OperationsController(JdbcTemplate db,SessionController sessions,InventoryService inventory){this.db=db;this.sessions=sessions;this.inventory=inventory;}
 UUID tenant(Principal p,HttpSession s,String... roles){UUID t=sessions.activeTenant(p,s);if(roles.length>0&&!Set.of(roles).contains(sessions.verifiedRole(p,t)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return t;}
 UUID requirePermission(Principal p,HttpSession s,Role.Permission permission){UUID tenant=sessions.activeTenant(p,s);if(!Role.valueOf(sessions.verifiedRole(p,tenant)).allows(permission))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return tenant;}
 @GetMapping("/orders") Object orders(Principal p,HttpSession s,@RequestParam(defaultValue="") String status,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="200") int size,jakarta.servlet.http.HttpServletResponse response){PageQuery paging=new PageQuery(page,size);if(!Set.of("","NEW","RESERVED","CANCELLED","SHIPPED").contains(status)||search.length()>100)throw bad();UUID t=tenant(p,s);response.setHeader("X-Total-Count",String.valueOf(db.queryForObject("select count(*) from sales_order where tenant_id=? and (?='' or status=?) and position(lower(?) in lower(external_id))>0",Long.class,t,status,status,search)));return db.queryForList("select id,store,external_id,status,sync_review_required,platform_fulfillment_status,externally_fulfilled,import_voided,currency,inventory_revision,net::text as net from sales_order where tenant_id=? and (?='' or status=?) and position(lower(?) in lower(external_id))>0 order by created_at desc,id limit ? offset ?",t,status,status,search,size,paging.offset());}
 @GetMapping("/inventory") Object stock(Principal p,HttpSession s,@RequestParam(defaultValue="00000000-0000-0000-0000-000000000001") UUID warehouseId,@RequestParam(defaultValue="") String search,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="200") int size,jakarta.servlet.http.HttpServletResponse response){PageQuery paging=new PageQuery(page,size);if(search.length()>100)throw bad();UUID t=tenant(p,s);response.setHeader("X-Total-Count",String.valueOf(db.queryForObject("select count(*) from inventory i join sku s on s.id=i.sku_id and s.tenant_id=i.tenant_id where i.tenant_id=? and i.warehouse_id=? and position(lower(?) in lower(s.code))>0",Long.class,t,warehouseId,search)));return db.queryForList("select s.id,i.warehouse_id,w.name as warehouse_name,s.code,s.name,i.on_hand,i.reserved,i.on_hand-i.reserved as available from inventory i join sku s on s.id=i.sku_id and s.tenant_id=i.tenant_id join warehouse w on w.tenant_id=i.tenant_id and w.id=i.warehouse_id where i.tenant_id=? and i.warehouse_id=? and position(lower(?) in lower(s.code))>0 order by s.code,s.id limit ? offset ?",t,warehouseId,search,size,paging.offset());}
 @GetMapping("/inventory/movements") Object movements(Principal p,HttpSession s){return db.queryForList("select * from (select m.id,s.code,m.kind,m.quantity,m.created_at,m.warehouse_id from inventory_movement m join sku s on s.id=m.sku_id and s.tenant_id=m.tenant_id where m.tenant_id=? union all select r.request_key as id,s.code,'receipt' as kind,r.quantity,r.created_at,r.warehouse_id from stock_receipt r join sku s on s.id=r.sku_id and s.tenant_id=r.tenant_id where r.tenant_id=? union all select v.correction_id as id,s.code,'receipt_reverse' as kind,-v.quantity as quantity,v.created_at,v.warehouse_id from receipt_reversal v join sku s on s.id=v.sku_id and s.tenant_id=v.tenant_id where v.tenant_id=? union all select a.id,k.code,a.kind,case when a.kind='RECEIPT_PARTIAL' then -a.quantity else a.quantity end as quantity,a.created_at,a.warehouse_id from business_adjustment a join sku k on k.tenant_id=a.tenant_id and k.id=a.sku_id where a.tenant_id=?) entries order by created_at desc limit 200",tenant(p,s),tenant(p,s),tenant(p,s),tenant(p,s));}
 record TransitionRequest(Long revision){}
 @PostMapping("/orders/{id}/{action}") @Transactional Object transition(@PathVariable UUID id,@PathVariable String action,@RequestBody(required=false) TransitionRequest request,Principal p,HttpSession s){if(!Set.of("reserve","cancel").contains(action))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"发货请使用运单接口");UUID t=tenant(p,s,action.equals("ship")?new String[]{"ADMIN","WAREHOUSE"}:new String[]{"ADMIN","OPERATIONS"});Object proposal=BusinessWorkflows.propose(db,t,p.getName(),action.equals("reserve")?"ORDER_RESERVE":"ORDER_CANCEL",id.toString(),request==null?new TransitionRequest(null):request);if(proposal!=null)return proposal;try{if(action.equals("reserve")){var current=db.queryForMap("select status,inventory_revision from sales_order where tenant_id=? and id=? for update",t,id);long revision=((Number)current.get("inventory_revision")).longValue();if(current.get("status").equals("NEW")&&(revision>0&&(request==null||request.revision()==null)||request!=null&&request.revision()!=null&&request.revision()!=revision))throw new ResponseStatusException(HttpStatus.CONFLICT,"订单预占轮次已变化，请刷新后重新操作");}inventory.transition(t,id,action);new Audit(db).record(t,p.getName(),"ORDER_"+action,id);return Map.of("status","APPLIED");}catch(org.springframework.dao.EmptyResultDataAccessException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}catch(IllegalStateException|IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage());}}
 record Csv(String csv,UUID warehouseId,UUID requestKey,String previewDigest){}
 @PostMapping("/orders/import/preview") @Transactional(readOnly=true) Object previewCsv(@RequestBody Csv input,Principal p,HttpSession s){UUID t=tenant(p,s,"ADMIN","OPERATIONS");UUID warehouse=input.warehouseId()==null?UUID.fromString("00000000-0000-0000-0000-000000000001"):input.warehouseId();return new CsvOrders(db).preview(t,warehouse,input.csv());}
 @PostMapping("/orders/import") @Transactional Object importCsv(@RequestBody Csv input,Principal p,HttpSession s){UUID t=tenant(p,s,"ADMIN","OPERATIONS");UUID warehouse=input.warehouseId()==null?UUID.fromString("00000000-0000-0000-0000-000000000001"):input.warehouseId();var preview=(Map<?,?>)new CsvOrders(db).preview(t,warehouse,input.csv());if(!Boolean.TRUE.equals(preview.get("canImport")))throw bad();Csv fixed=new Csv(input.csv(),warehouse,input.requestKey()==null?UUID.randomUUID():input.requestKey(),input.previewDigest()==null?(String)preview.get("digest"):input.previewDigest());Object proposal=BusinessWorkflows.propose(db,t,p.getName(),"CSV_IMPORT",warehouse.toString(),fixed);if(proposal!=null)return proposal;return new CsvOrders(db).importOrders(t,warehouse,input.csv(),p.getName(),fixed.requestKey(),fixed.previewDigest());} ResponseStatusException bad(){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"CSV格式无效，请使用指定模板；最多500行、100000字符");}
}
